<?php $pageTitle='Buscar';require_once __DIR__.'/includes/config.php';$term=trim($_GET['q']??'');$articles=[];if($term!==''){[$s,$args]=visible_where();$sql="SELECT * FROM news_articles WHERE ".article_visibility_sql()." AND (headline LIKE ? OR subheadline LIKE ? OR body LIKE ?) ORDER BY breaking DESC,phase_required DESC,priority DESC";$q=db()->prepare($sql);$like='%'.$term.'%';$q->execute([...$args,$like,$like,$like]);$articles=$q->fetchAll();}include __DIR__.'/includes/header.php';?><section class="wrap section-page"><h1>Buscar</h1><form class="search"><input name="q" value="<?=h($term)?>" placeholder="Busca noticias, temas o protagonistas…"><button>Buscar</button></form><?php if($term):?><p><?=count($articles)?> resultados para <b><?=h($term)?></b></p><div class="archive"><?php foreach($articles as $a):?><a data-news-id="<?=(int)$a['id']?>" data-news-new="<?=article_is_new($a,$state)?'1':'0'?>" href="/nota.php?slug=<?=h($a['slug'])?>"><span><?=h($a['category'])?></span><b><?=h($a['headline'])?></b></a><?php endforeach;?></div><?php endif;?></section><script>window.PULSO_LIVE=true;</script><?php include __DIR__.'/includes/footer.php';?>